insert into public.sq_lorekeeper (term_id, is_active, grade_level, passage, question, choice_a, choice_b, choice_c, choice_d, correct_choice) values
  (1, true, 6, NULL, 'A virus is often debated among scientists regarding classification because it', 'Fits neatly into all six kingdoms equally', 'Does not have cells and shows characteristics of both living and non-living things', 'Is always classified under Kingdom Animalia', 'Has no scientific significance at all', 'b'),
  (1, true, 6, NULL, 'Which of these best explains why fungi are classified separately from plants, even though both may appear stationary?', 'Fungi absorb nutrients from their environment rather than making their own food through photosynthesis', 'Fungi and plants are biologically identical', 'Fungi can photosynthesize better than plants', 'There is no real difference between fungi and plants', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the term "endangered species"?', 'A species at serious risk of becoming extinct in the near future', 'A species with an unusually large population', 'A species that has already gone extinct', 'A term with no real scientific meaning', 'a'),
  (1, true, 6, NULL, 'Which of these is an example of a human activity that can help restore biodiversity in a damaged ecosystem?', 'Reforestation and habitat restoration projects', 'Continued unchecked deforestation', 'Introducing more invasive species', 'Ignoring pollution sources', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the greenhouse effect''s connection to climate change?', 'Excess greenhouse gases trap heat in the atmosphere, contributing to global warming', 'Greenhouse gases have no effect on global temperature', 'The greenhouse effect only cools the planet', 'Climate change has no scientific explanation', 'a'),
  (1, true, 6, NULL, 'The ''Pacific Ring of Fire'' refers to', 'A region around the Pacific Ocean known for frequent earthquakes and volcanic activity', 'A literal ring of fire visible from space', 'A calm region with no tectonic activity', 'A term used only for ocean currents', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why scientists monitor active volcanoes closely?', 'To detect warning signs of eruption and help protect nearby communities', 'Volcanoes never show any warning signs before erupting', 'Monitoring volcanoes serves no practical purpose', 'Volcanic eruptions cannot be predicted or studied at all', 'a'),
  (1, true, 6, NULL, 'A caldera is best described as', 'A large, bowl-shaped depression formed after a volcanic eruption or collapse', 'A type of earthquake wave', 'A tool used to measure wind speed', 'A type of tectonic plate', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why buildings in earthquake-prone areas like the Philippines are often designed with special engineering features?', 'To help structures withstand shaking and reduce damage or collapse during earthquakes', 'Earthquake-resistant design has no real benefit', 'Buildings are never affected by earthquakes', 'Special engineering only affects a building''s appearance', 'a'),
  (1, true, 6, NULL, 'Deposition, the process where sediment settles and builds up in a new location, often occurs after which process?', 'Weathering and erosion transport material that is then deposited elsewhere', 'Deposition always happens before weathering', 'Deposition has no relationship with erosion', 'Deposition only occurs underground', 'a'),
  (1, true, 6, NULL, 'An ammeter is a tool used to measure', 'Electric current in a circuit', 'Wind speed', 'Earthquake magnitude', 'Rock hardness', 'a'),
  (1, true, 6, NULL, 'A voltmeter is a tool used to measure', 'Electric current only', 'Voltage (electrical potential difference)', 'Wind direction', 'Sound pitch', 'b'),
  (1, true, 6, NULL, 'Which of these best explains how a simple electric motor converts electrical energy into motion?', 'Electric current flowing through a coil in a magnetic field creates a force that produces rotation', 'Motors work through sound waves alone', 'Electric motors have no connection to magnetism', 'Motors convert light energy directly into motion', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why static electricity can cause a small shock when touching a metal doorknob after walking on carpet?', 'Built-up electric charge on your body suddenly discharges through the conductor', 'Metal doorknobs generate their own electricity independently', 'Carpet has no effect on electric charge', 'Static electricity cannot cause any physical sensation', 'a'),
  (1, true, 6, NULL, 'Which of these best describes a responsible way to seek accurate information about body changes during adolescence?', 'Asking trusted adults, school counselors, or verified educational resources', 'Believing every unverified claim seen online without question', 'Avoiding the topic entirely and never asking questions', 'Relying only on rumors from unreliable sources', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why balanced nutrition and adequate sleep are especially important during the growth of adolescence?', 'The body requires proper nutrients and rest to support the physical and mental changes occurring during this stage', 'Nutrition and sleep have no connection to physical development', 'The body needs less nutrition during growth spurts', 'Sleep becomes unnecessary during adolescence', 'a'),
  (1, true, 6, 'The Great Wall of China, built and rebuilt over centuries by various dynasties, was constructed primarily as a defensive structure to protect against invasions from northern nomadic groups.', 'According to the passage, what was the primary purpose of the Great Wall of China?', 'To serve as a defensive structure against invasions', 'To serve as a marketplace', 'To connect trade routes only', 'To function as a religious temple', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the significance of ancient Japan''s feudal system, which included samurai warriors?', 'It structured Japanese society around loyalty, land, and military service for centuries', 'It had no lasting influence on Japanese history or culture', 'It was identical to the systems used in Mesopotamia', 'It only existed for a few days', 'a'),
  (1, true, 6, NULL, 'Which of these best describes why the Indus Valley Civilization''s writing system remains a mystery to modern historians?', 'Its script has not yet been fully deciphered by researchers', 'The civilization never developed any writing at all', 'Modern historians have no interest in studying it', 'The script has been completely translated with no remaining questions', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why the study of ancient civilizations often relies on both archaeology and written records?', 'Physical artifacts and written texts together provide a more complete understanding of the past', 'Archaeology and written records always contradict each other with no value', 'Only written records matter; artifacts are irrelevant', 'Only artifacts matter; written records are irrelevant', 'a'),
  (1, true, 6, NULL, 'Emilio Aguinaldo is significant in Philippine history mainly for', 'Declaring Philippine independence from Spain in 1898 and later becoming the first Philippine president', 'Leading the American colonial government', 'Serving as a Thomasite teacher', 'Leading the People Power Revolution', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why the Philippines experienced significant infrastructure damage during World War II?', 'Major battles and Japanese occupation caused widespread destruction across the country', 'World War II had no effect on the Philippines at all', 'The Philippines was never involved in World War II', 'Infrastructure was undamaged throughout the war', 'a'),
  (1, true, 6, NULL, 'Which of these best describes why the 1986 EDSA Revolution is often called a "peaceful" revolution?', 'It was largely achieved through nonviolent mass demonstrations rather than armed conflict', 'It involved a prolonged violent civil war', 'No citizens were involved in the events', 'It was resolved entirely through international military intervention', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why understanding Martial Law (1972–1986) is important for studying Philippine democracy?', 'It shows the consequences of concentrated power and the value of restored democratic institutions', 'Martial Law has no connection to Philippine democratic history', 'It only affected a single city with no national impact', 'It strengthened checks and balances immediately', 'a'),
  (1, true, 6, NULL, 'Which of these best describes a monopoly in economics?', 'A market situation where a single seller controls the entire supply of a good or service', 'A market with many competing sellers', 'A government-run charity', 'A type of tax', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why competition among businesses can benefit consumers?', 'It can lead to lower prices, better quality, and more innovation', 'Competition always raises prices for consumers', 'Competition has no effect on markets', 'Competition only benefits large businesses, never consumers', 'a'),
  (1, true, 6, NULL, 'Which of these best describes how a cooperative differs from a typical private corporation?', 'A cooperative is owned and controlled by its members for mutual benefit, rather than by outside shareholders seeking profit alone', 'There is no difference between the two', 'A cooperative is always owned by the government', 'A corporation always has more members than a cooperative', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the impeachment process for high government officials in the Philippines?', 'A formal legal process where Congress can remove an official from office for serious offenses', 'A process that has never existed in Philippine law', 'A vote taken only by the President personally', 'A ceremonial title with no legal weight', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the importance of an independent judiciary in a democratic government?', 'It ensures laws are interpreted fairly, without undue influence from the other branches', 'An independent judiciary weakens the rule of law', 'Judges should always follow orders from the executive branch', 'Judicial independence has no role in democracy', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the purpose of a barangay assembly or barangay council meeting?', 'To discuss and address local community concerns and pass local ordinances', 'To handle only national-level legislation', 'To replace the national Congress', 'It serves no practical function', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why global organizations like the UN rely on the cooperation of member states rather than direct control over them?', 'The UN respects national sovereignty while encouraging collaboration on shared global issues', 'The UN has direct military and legal control over every country', 'Member states have no say in UN decisions', 'The UN replaces national governments entirely', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the importance of international cooperation during a global health crisis, based on the role of organizations like WHO?', 'Diseases can cross borders, so coordinated global response and information sharing help contain outbreaks effectively', 'Diseases never spread beyond a single country', 'International cooperation makes health crises worse', 'Countries should never share health information', 'a'),
  (1, true, 6, NULL, 'In a literary work, the antagonist is best described as', 'The character or force that opposes the main character', 'The narrator of the story', 'The setting of the story', 'The author of the text', 'a'),
  (1, true, 6, NULL, 'In a literary work, the protagonist is best described as', 'The main character around whom the story revolves', 'A minor character with no importance', 'The setting of the story', 'A literary device only', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the purpose of exposition at the beginning of a story?', 'To introduce characters, setting, and background information needed to understand the plot', 'To reveal the story''s ending immediately', 'To provide no useful information to the reader', 'To replace the need for a plot entirely', 'a'),
  (1, true, 6, NULL, 'Which of these best explains how tone differs from mood in a literary work?', 'Tone reflects the author''s attitude toward the subject, while mood is the atmosphere or feeling created for the reader', 'Tone and mood are exactly the same concept', 'Mood refers only to the author''s opinion', 'Tone refers only to the reader''s emotional reaction', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why an author might choose an ambiguous or open ending for a story?', 'To encourage readers to interpret the outcome and reflect on the story''s themes', 'To confuse readers with no literary purpose', 'Ambiguous endings are never used in serious literature', 'It eliminates the need for a plot altogether', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the purpose of an introduction paragraph in an argumentative essay?', 'To present the topic, provide context, and state the writer''s claim (thesis)', 'To provide the conclusion of the essay', 'To list only the sources used', 'To restate the counterargument exclusively', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why a strong conclusion is important in a persuasive essay?', 'It reinforces the writer''s claim and leaves a lasting impression on the reader', 'Conclusions have no real purpose in persuasive writing', 'A conclusion should always introduce new evidence not mentioned earlier', 'The conclusion should contradict the writer''s claim', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why evaluating an author''s credentials is part of assessing source reliability?', 'An author''s expertise and background can indicate the credibility of the information they present', 'An author''s background never matters', 'All authors are equally credible regardless of expertise', 'Credentials have no connection to reliability', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the difference between a summary and a paraphrase?', 'A summary condenses the main ideas, while a paraphrase restates the full content in different words', 'They are exactly the same thing', 'A summary is always longer than the original text', 'A paraphrase always uses the exact original wording', 'a'),
  (1, true, 6, NULL, 'Which sentence uses a mixed conditional correctly (combining a past condition with a present result)?', 'If I had studied medicine, I would be a doctor now.', 'If I study medicine, I will be a doctor now.', 'If I studied medicine, I will have been a doctor.', 'If I had studied medicine, I will be a doctor.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses reported speech to report a command?', 'The teacher told the students to be quiet.', 'The teacher told, "Be quiet, students."', 'The teacher told the students be quiet.', 'The teacher told to the students quiet be.', 'a'),
  (1, true, 6, NULL, 'Which sentence correctly uses a restrictive relative clause (no commas, essential information)?', 'The student who finished first won a prize.', 'The student, who finished first, won a prize.', 'The student who, finished first won, a prize.', 'The student won, who finished first, a prize.', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the difference in meaning between "jealous" and "envious"?', 'Jealous often implies fear of losing something one has, while envious implies wanting something someone else has', 'They are exactly identical in every context', 'Jealous always means happy for someone else', 'Envious always means content with what one has', 'a'),
  (1, true, 6, NULL, 'The idiomatic expression "burn the midnight oil" means to', 'Work or study late into the night', 'Literally burn oil for light', 'Waste time doing nothing', 'Go to sleep early', 'a'),
  (1, true, 6, NULL, 'The idiomatic expression "bite the bullet" means to', 'Face a difficult situation with courage', 'Literally bite something made of metal', 'Avoid all challenges', 'Give up immediately', 'a'),
  (1, true, 6, NULL, 'Ang uring dulang seryoso ang paksa at kadalasang tumatalakay sa mahahalagang usapin sa lipunan ay tinatawag na', 'Dulang seryoso (drama)', 'Komedya', 'Musikal', 'Parody', 'a'),
  (1, true, 6, NULL, 'Sa isang dula, ang saglit na pagbabago ng eksena o tagpuan ay maaaring ipahiwatig sa pamamagitan ng', 'Direksyon sa entablado', 'Pandiwang perpektibo', 'Pang-uri', 'Panghalip', 'a'),
  (1, true, 6, NULL, 'Bakit mahalaga ang wastong pagkakasunod-sunod ng mga pangyayari (banghay) sa isang dula?', 'Upang maunawaan ng manonood ang daloy at kahulugan ng kwento', 'Walang kabuluhan ang pagkakasunod-sunod ng pangyayari', 'Hindi ito bahagi ng isang dula', 'Ito ay ginagamit lamang sa tula', 'a'),
  (1, true, 6, NULL, 'Sa pagsulat ng talambuhay, mahalagang isaalang-alang ang', 'Kronolohikal na pagkakasunod-sunod ng mga mahahalagang pangyayari sa buhay ng paksa', 'Basta anumang pagkakasunod-sunod nang walang pattern', 'Kathang-isip na detalye lamang', 'Walang partikular na estruktura', 'a'),
  (1, true, 6, NULL, 'Ang layunin ng isang deduktibong pangangatwiran ay', 'Iparating ang isang tiyak na konklusyon batay sa isang pangkalahatang alituntunin', 'Gumawa ng pangkalahatang konklusyon batay sa tiyak na obserbasyon', 'Walang layunin', 'Palaging magbigay ng maling impormasyon', 'a'),
  (1, true, 6, NULL, 'Bakit mahalagang gumamit ng ebidensya sa isang retorikang pahayag?', 'Upang gawing mas kapani-paniwala at matatag ang argumento', 'Ebidensya ay hindi kailanman kailangan sa isang argumento', 'Nagpapahina lamang ito sa isang pahayag', 'Walang kaugnayan ang ebidensya sa retorika', 'a'),
  (1, true, 6, NULL, 'Alin sa mga sumusunod ang tanda ng maaaring hindi mapagkakatiwalaang teksto?', 'Walang batayan o ebidensya ang mga pahayag nito', 'May malinaw na sanggunian at ebidensya', 'Isinulat ng isang eksperto sa paksa', 'Sinuri ng ibang eksperto bago ito nailathala', 'a'),
  (1, true, 6, NULL, 'Sa pagsusuri ng bias, mahalagang tingnan kung ang manunulat ay', 'Nagpapakita ng patas na presentasyon ng lahat ng panig ng isang isyu', 'Basta sumusulat nang walang paksa', 'Hindi kailanman nagbibigay ng opinyon', 'Palaging sumasang-ayon sa lahat ng bagay', 'a'),
  (1, true, 6, NULL, 'Ang pandiwang "kumakain" ay nasa anong aspekto?', 'Perpektibo', 'Imperpektibo', 'Kontemplatibo', 'Wala sa mga ito', 'b'),
  (1, true, 6, NULL, 'Ang pandiwang "tatakbo" ay nasa anong aspekto?', 'Perpektibo', 'Imperpektibo', 'Kontemplatibo', 'Wala sa mga ito', 'c'),
  (1, true, 6, NULL, 'Ang pandiwang "tumakbo" ay nasa anong aspekto?', 'Perpektibo', 'Imperpektibo', 'Kontemplatibo', 'Wala sa mga ito', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why Grade 6 students study both the branches of government and international organizations in the same unit?', 'Understanding how a nation governs itself helps connect to how nations cooperate globally', 'The two topics have no relationship whatsoever', 'International organizations replace the need for national government', 'Studying government has no relevance to global cooperation', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why the Philippines'' history under multiple colonial powers (Spain, then the United States, then Japan) shaped its modern culture?', 'Each period left lasting influences on language, religion, government, and traditions', 'Colonial history had no lasting cultural impact', 'The Philippines was never influenced by any foreign power', 'Only one colonial period had any effect on the country', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why understanding plate tectonics helps explain both earthquake and volcano patterns worldwide?', 'Both phenomena are directly related to the movement and interaction of tectonic plates', 'Earthquakes and volcanoes have completely unrelated causes', 'Plate tectonics only explains earthquakes, never volcanoes', 'Plate tectonics only explains volcanoes, never earthquakes', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why circuit diagrams use standardized symbols for components like batteries, switches, and bulbs?', 'Standardized symbols allow anyone to read and understand a circuit diagram consistently', 'Circuit diagrams have no need for consistent symbols', 'Every country uses completely different circuit symbols with no overlap', 'Symbols in circuit diagrams are purely decorative', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why understanding both primary and secondary sources is important in historical research?', 'Primary sources offer direct evidence, while secondary sources provide analysis and context, together giving a fuller picture', 'Only secondary sources matter in historical research', 'Only primary sources matter in historical research', 'Neither type of source is useful for research', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the term "extinction"?', 'The complete disappearance of a species from Earth', 'A temporary decrease in population', 'A species moving to a new habitat', 'A species growing in number', 'a'),
  (1, true, 6, NULL, 'Which of these is a renewable natural resource?', 'Solar energy', 'Coal', 'Natural gas', 'Petroleum', 'a'),
  (1, true, 6, NULL, 'Which of these is a non-renewable natural resource?', 'Wind energy', 'Coal', 'Sunlight', 'Fresh air', 'b'),
  (1, true, 6, NULL, 'A tsunami is most commonly triggered by which of these events?', 'An underwater earthquake or volcanic eruption', 'A light breeze', 'A sunny day', 'A drought', 'a'),
  (1, true, 6, NULL, 'Which of these best describes a fault line?', 'A fracture in the Earth''s crust where blocks of rock have shifted relative to each other', 'A type of ocean current', 'A form of renewable energy', 'A weather pattern', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the purpose of a lightning rod on a building?', 'To safely direct a lightning strike''s electrical current into the ground', 'To attract more lightning strikes for decoration', 'To block all electricity from entering a building', 'It has no real function', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the function of a fuse in an electrical system?', 'It breaks the circuit automatically if current flow becomes dangerously high, preventing fires', 'It permanently increases voltage', 'It has no safety function', 'It converts electricity into heat only for cooking', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the biological purpose of the changes that occur during adolescence?', 'They prepare the body for physical maturity into adulthood', 'They serve no biological purpose', 'They only affect a person''s eye color', 'They happen only to prevent growth', 'a'),
  (1, true, 6, NULL, 'Confucius, an influential philosopher from ancient China, is best known for teachings about', 'Ethics, morality, and proper social relationships', 'Volcanic eruptions', 'Modern computer science', 'Ocean navigation only', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the historical importance of the invention of woodblock printing in ancient China?', 'It allowed texts to be reproduced and spread more widely than by hand-copying alone', 'It had no impact on the spread of knowledge', 'It was invented after European printing', 'It was used only for currency', 'a'),
  (1, true, 6, NULL, 'The Katipunan, founded by Andres Bonifacio, played what role in Philippine history?', 'It was a secret society that led the revolution against Spanish rule', 'It was a Spanish colonial government office', 'It was an American educational program', 'It had no role in Philippine independence movements', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the long-term economic effects of Martial Law-era debt on the Philippines?', 'Large loans taken during this period contributed to economic challenges in following decades', 'The debt had no lasting economic effect', 'The Philippines had no debt during this period', 'Martial Law improved the economy with no downsides', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the role of the Commission on Elections (COMELEC) in the Philippines?', 'It administers and oversees national and local elections', 'It is responsible for foreign trade agreements', 'It manages the national budget exclusively', 'It has no role in Philippine governance', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the purpose of the Philippine Constitution?', 'It serves as the supreme law, outlining government structure and citizens'' rights', 'It is a historical document with no legal power today', 'It applies only to government officials, not citizens', 'It has been replaced entirely by international law', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why elections are important in a democratic system like the Philippines?', 'They allow citizens to choose their leaders and hold government accountable', 'Elections have no real impact on governance', 'Only government officials are allowed to vote', 'Elections are held only once per century', 'a'),
  (1, true, 6, NULL, 'Which of these best describes the difference between a democracy and a dictatorship?', 'A democracy involves power held by elected representatives accountable to citizens, while a dictatorship concentrates power in one ruler with little accountability', 'They are exactly the same system of government', 'A dictatorship always has free elections', 'A democracy has no elected officials', 'a'),
  (1, true, 6, NULL, 'Which of these best explains the significance of freedom of the press in a democratic society?', 'It allows journalists to report on government actions and inform the public, promoting accountability', 'A free press has no role in democracy', 'Freedom of the press means journalists can never be held accountable for false claims', 'It only applies to entertainment news', 'a'),
  (1, true, 6, NULL, 'In a persuasive speech, which technique involves appealing to the audience''s emotions?', 'Pathos', 'Logos', 'Ethos', 'Syntax', 'a'),
  (1, true, 6, NULL, 'In a persuasive speech, which technique involves appealing to logic and reasoning?', 'Pathos', 'Logos', 'Ethos', 'Diction only', 'b'),
  (1, true, 6, NULL, 'In a persuasive speech, which technique involves appealing to the speaker''s credibility?', 'Pathos', 'Logos', 'Ethos', 'Meter only', 'c'),
  (1, true, 6, NULL, 'Which of these best explains why a writer might use a rhetorical question in a persuasive essay?', 'To engage the reader and emphasize a point without expecting a literal answer', 'To confuse the reader with no purpose', 'Rhetorical questions are never used in persuasive writing', 'To replace the need for evidence entirely', 'a'),
  (1, true, 6, NULL, 'Ang "ethos," "pathos," at "logos" ay mga estratehiyang ginagamit sa', 'Panghihikayat o pagbubuo ng matibay na argumento', 'Pagsulat ng tula lamang', 'Pagbibilang ng numero', 'Walang gamit sa pagsulat', 'a'),
  (1, true, 6, NULL, 'Ang katapatan at kawastuhan ng impormasyon sa isang talambuhay ay dapat', 'Suriin at patunayan gamit ang maaasahang mga sanggunian', 'Hindi na kailangang suriin', 'Basta paniwalaan nang walang pag-aalinlangan', 'Walang kaugnayan sa kalidad ng akda', 'a'),
  (1, true, 6, NULL, 'Bakit mahalagang gamitin ang tamang pandiwang aspekto kapag nagsasalaysay ng isang pangyayari?', 'Upang malinaw na maipahayag kung kailan naganap ang kilos', 'Wala itong epekto sa pag-unawa ng mambabasa', 'Ginagamit lamang ito sa pormal na pagsusulat', 'Hindi na ito kailangan sa modernong Filipino', 'a'),
  (1, true, 6, NULL, 'Which of these best explains why understanding both ancient civilizations and modern government systems helps students become informed citizens?', 'It provides historical context for how societies govern themselves and evolve over time', 'History and government have no connection to citizenship', 'Only modern events matter for citizenship education', 'Ancient history has no relevance to understanding government', 'a');